function mergeHeaders(
	...headerSources: (Record<string, string | null> | undefined)[]
): Record<string, string | null> {
	const merged: Record<string, string | null> = {};
	for (const headers of headerSources) {
		for (const [name, value] of Object.entries(headers ?? {})) {
			merged[name.toLowerCase()] = value;
		}
	}
	return merged;
}

function headersToRecord(headers: Headers): Record<string, string> {
	return Object.fromEntries(headers.entries());
}

function appendBetaQuery(url: URL): URL {
	if (url.pathname === "/v1/messages" && !url.searchParams.has("beta")) {
		url.searchParams.set("beta", "true");
	}
	return url;
}

function stripAnthropicCcTransportHeaders(headers?: HeadersInit): Headers | undefined {
	if (!headers) return undefined;
	const next = new Headers(headers);
	// Narrow parity override: the Anthropic SDK stream helper adds this transport header,
	// but current Claude Code captures do not include it.
	next.delete("X-Stainless-Helper-Method");
	next.delete("x-stainless-helper-method");
	return next;
}

function withMessagesBetaQuery(fetchImpl: typeof fetch = globalThis.fetch.bind(globalThis)): typeof fetch {
	return ((input: RequestInfo | URL, init?: RequestInit) => {
		if (input instanceof Request) {
			const url = appendBetaQuery(new URL(input.url));
			const request = new Request(url, input);
			request.headers.delete("X-Stainless-Helper-Method");
			request.headers.delete("x-stainless-helper-method");
			return fetchImpl(request, { ...init, headers: stripAnthropicCcTransportHeaders(init?.headers) });
		}
		const url = appendBetaQuery(new URL(typeof input === "string" ? input : input.toString()));
		return fetchImpl(input instanceof URL ? url : url.toString(), {
			...init,
			headers: stripAnthropicCcTransportHeaders(init?.headers),
		});
	}) as typeof fetch;

